/** @file GeneratedAssetCache.js @description IndexedDB cache spine for generated world vessels. */
export const GENERATED_CACHE_DB = "awtsmoosMitzvahGeneratedAssets";
export const GENERATED_CACHE_VERSION = "generated-cache-spine-20260701-bh1";
const STORE = "assets";
let dbPromise = null;
const idb = () => typeof indexedDB !== "undefined" ? indexedDB : null;
const nav = () => typeof navigator !== "undefined" ? navigator : null;
export function stableStringify(value) { if (value == null || typeof value !== "object") return JSON.stringify(value); if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`; return `{${Object.keys(value).sort().map(k => `${JSON.stringify(k)}:${stableStringify(value[k])}`).join(",")}}`; }
export function hashString(text = "") { let h = 2166136261; for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 16777619); return (h >>> 0).toString(36); }
export function makeGeneratedCacheKey({ kind = "asset", version = GENERATED_CACHE_VERSION, seed = "default", source = "world", settings = {} } = {}) { return `${kind}:${version}:${hashString(`${seed}|${source}|${stableStringify(settings)}`)}`; }
function openDb() { if (!idb()) return Promise.resolve(null); if (dbPromise) return dbPromise; dbPromise = new Promise(resolve => { const req = idb().open(GENERATED_CACHE_DB, 1); req.onupgradeneeded = () => { const db = req.result, store = db.objectStoreNames.contains(STORE) ? req.transaction.objectStore(STORE) : db.createObjectStore(STORE, { keyPath:"key" }); if (!store.indexNames.contains("kind")) store.createIndex("kind", "kind", { unique:false }); if (!store.indexNames.contains("updatedAt")) store.createIndex("updatedAt", "updatedAt", { unique:false }); }; req.onsuccess = () => resolve(req.result); req.onerror = () => resolve(null); req.onblocked = () => resolve(null); }); return dbPromise; }
function bytesOf(value) { if (!value) return 0; if (value instanceof ArrayBuffer) return value.byteLength; if (ArrayBuffer.isView(value)) return value.byteLength; if (typeof Blob !== "undefined" && value instanceof Blob) return value.size; if (typeof value === "string") return value.length * 2; if (value.value) return bytesOf(value.value); try { return stableStringify(value).length * 2; } catch { return 0; } }
function txDone(tx, fallback) { return new Promise(resolve => { tx.oncomplete = () => resolve(true); tx.onerror = () => resolve(fallback); tx.onabort = () => resolve(fallback); }); }
export async function getGeneratedAsset(key) { const db = await openDb(); if (!db || !key) return null; return new Promise(resolve => { const req = db.transaction(STORE, "readonly").objectStore(STORE).get(key); req.onsuccess = () => resolve(req.result || null); req.onerror = () => resolve(null); }); }
export async function putGeneratedAsset(key, value, meta = {}) { const db = await openDb(); if (!db || !key) return { ok:false, reason:"indexeddb-unavailable" }; const record = { key, value, kind:meta.kind || "asset", version:meta.version || GENERATED_CACHE_VERSION, bytes:bytesOf(value), meta, updatedAt:Date.now() }; const tx = db.transaction(STORE, "readwrite"); tx.objectStore(STORE).put(record); return { ok:await txDone(tx, false), key, bytes:record.bytes, kind:record.kind }; }
export async function clearGeneratedAssetCache() { const db = await openDb(); if (!db) return { ok:false, reason:"indexeddb-unavailable" }; const tx = db.transaction(STORE, "readwrite"); tx.objectStore(STORE).clear(); return { ok:await txDone(tx, false) }; }
export async function deleteGeneratedAssetKind(kind) { const db = await openDb(); if (!db || !kind) return { ok:false }; return new Promise(resolve => { const tx = db.transaction(STORE, "readwrite"), idx = tx.objectStore(STORE).index("kind"); let deleted = 0; idx.openCursor(IDBKeyRange.only(kind)).onsuccess = event => { const cur = event.target.result; if (!cur) return; deleted += 1; cur.delete(); cur.continue(); }; tx.oncomplete = () => resolve({ ok:true, deleted, kind }); tx.onerror = () => resolve({ ok:false, deleted, kind }); }); }
export async function estimateGeneratedAssetCache() { const native = await Promise.resolve().then(() => nav()?.storage?.estimate?.()).catch(() => null); const db = await openDb(); if (!db) return { ok:false, bytes:0, entries:0, native }; return new Promise(resolve => { let bytes = 0, entries = 0; const req = db.transaction(STORE, "readonly").objectStore(STORE).openCursor(); req.onsuccess = () => { const cur = req.result; if (!cur) return resolve({ ok:true, bytes, entries, native }); bytes += Number(cur.value?.bytes || 0); entries += 1; cur.continue(); }; req.onerror = () => resolve({ ok:false, bytes, entries, native }); }); }
export function installGeneratedCacheGlobals(scope = globalThis) { if (!scope) return; scope.__AWTSMOOS_GENERATED_CACHE_ESTIMATE__ = estimateGeneratedAssetCache; scope.__AWTSMOOS_GENERATED_CACHE_CLEAR__ = clearGeneratedAssetCache; scope.__AWTSMOOS_GENERATED_CACHE_CLEAR_KIND__ = deleteGeneratedAssetKind; scope.__AWTSMOOS_GENERATED_CACHE_KEY__ = makeGeneratedCacheKey; }
installGeneratedCacheGlobals();
